PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE db_migration (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        version VARCHAR(32) NOT NULL UNIQUE,
        description VARCHAR(256),
        applied_at DATETIME NOT NULL,
        status VARCHAR(16) DEFAULT 'success'
    );
CREATE TABLE sys_announcement (
	id INTEGER NOT NULL, 
	title VARCHAR(256) NOT NULL, 
	content TEXT, 
	type VARCHAR(16), 
	is_popup BOOLEAN, 
	publish_time DATETIME, 
	expire_time DATETIME, 
	status BOOLEAN, 
	created_by VARCHAR(64), 
	created_by_id INTEGER, 
	created_at DATETIME, visible_scope VARCHAR(16) DEFAULT "all", visible_roles TEXT, visible_depts TEXT, 
	PRIMARY KEY (id)
);
CREATE TABLE sys_role (
	id INTEGER NOT NULL, 
	role_code VARCHAR(64) NOT NULL, 
	role_name VARCHAR(128) NOT NULL, 
	data_scope VARCHAR(16), 
	status BOOLEAN, 
	sort INTEGER, 
	remark VARCHAR(256), 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	UNIQUE (role_code)
);
CREATE TABLE sys_menu (
	id INTEGER NOT NULL, 
	parent_id INTEGER, 
	menu_name VARCHAR(128) NOT NULL, 
	menu_code VARCHAR(64), 
	menu_type VARCHAR(16), 
	path VARCHAR(256), 
	component VARCHAR(256), 
	icon VARCHAR(64), 
	sort INTEGER, 
	status BOOLEAN, 
	permission VARCHAR(128), 
	remark VARCHAR(256), 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(parent_id) REFERENCES sys_menu (id), 
	UNIQUE (menu_code)
);
CREATE TABLE projects (
	id INTEGER NOT NULL, 
	name VARCHAR(128) NOT NULL, 
	code VARCHAR(64), 
	address VARCHAR(256), 
	start_date DATE, 
	planned_end_date DATE, 
	actual_end_date DATE, 
	manager VARCHAR(64), 
	contact_phone VARCHAR(32), 
	building_area NUMERIC(18, 2), 
	contract_amount NUMERIC(18, 2), 
	status VARCHAR(16), 
	project_type VARCHAR(32), 
	is_archived BOOLEAN, 
	module_config TEXT, 
	created_at DATETIME, 
	PRIMARY KEY (id)
);
CREATE TABLE payments (
	id INTEGER NOT NULL, 
	project_id INTEGER NOT NULL, 
	contract_id INTEGER NOT NULL, 
	supplier_id INTEGER NOT NULL, 
	payment_code VARCHAR(64) NOT NULL, 
	payment_date DATE, 
	amount NUMERIC(18, 2), 
	method VARCHAR(32), 
	approval_status VARCHAR(16), 
	source_application_id INTEGER, 
	amount_without_tax NUMERIC(18, 2), 
	tax_amount NUMERIC(18, 2), 
	remark TEXT, 
	created_at DATETIME, is_deleted BOOLEAN DEFAULT 0, deleted_at DATETIME, dept_id INTEGER, 
	PRIMARY KEY (id), 
	FOREIGN KEY(project_id) REFERENCES projects (id), 
	FOREIGN KEY(contract_id) REFERENCES contracts (id), 
	FOREIGN KEY(supplier_id) REFERENCES suppliers (id), 
	FOREIGN KEY(source_application_id) REFERENCES payment_applications (id)
);
CREATE TABLE payment_applications (
	id INTEGER NOT NULL, 
	project_id INTEGER NOT NULL, 
	application_code VARCHAR(64) NOT NULL, 
	apply_date DATE, 
	applicant_id INTEGER, 
	applicant_name VARCHAR(64), 
	supplier_id INTEGER NOT NULL, 
	contract_id INTEGER NOT NULL, 
	reconciliation_ids VARCHAR(512), 
	apply_amount NUMERIC(18, 2), 
	payment_method VARCHAR(32), 
	expected_payment_date DATE, 
	payment_description TEXT, 
	attachment VARCHAR(256), 
	status VARCHAR(16), 
	approval_status VARCHAR(16), 
	payment_id INTEGER, 
	change_reason VARCHAR(256), 
	remark TEXT, 
	created_at DATETIME, 
	updated_at DATETIME, dept_id INTEGER, 
	PRIMARY KEY (id), 
	FOREIGN KEY(project_id) REFERENCES projects (id), 
	FOREIGN KEY(applicant_id) REFERENCES users (id), 
	FOREIGN KEY(supplier_id) REFERENCES suppliers (id), 
	FOREIGN KEY(contract_id) REFERENCES contracts (id), 
	FOREIGN KEY(payment_id) REFERENCES payments (id)
);
CREATE TABLE system_config (
	id INTEGER NOT NULL, 
	config_key VARCHAR(64) NOT NULL, 
	config_value VARCHAR(256), 
	description VARCHAR(256), 
	updated_at DATETIME, 
	PRIMARY KEY (id)
);
CREATE TABLE sys_dict_type (
	id INTEGER NOT NULL, 
	dict_type VARCHAR(64) NOT NULL, 
	dict_name VARCHAR(128) NOT NULL, 
	remark VARCHAR(256), 
	is_active BOOLEAN, 
	created_at DATETIME, 
	PRIMARY KEY (id)
);
CREATE TABLE ai_call_log (
	id INTEGER NOT NULL, 
	user_id INTEGER, 
	username VARCHAR(64), 
	module VARCHAR(64), 
	prompt TEXT, 
	response TEXT, 
	input_tokens INTEGER, 
	output_tokens INTEGER, 
	cost_time INTEGER, 
	success BOOLEAN, 
	error_msg TEXT, 
	created_at DATETIME, 
	PRIMARY KEY (id)
);
CREATE TABLE approval_flow (
	id INTEGER NOT NULL, 
	flow_code VARCHAR(64) NOT NULL, 
	flow_name VARCHAR(128) NOT NULL, 
	biz_type VARCHAR(32) NOT NULL, 
	enabled BOOLEAN, 
	has_branch BOOLEAN, 
	description VARCHAR(256), 
	created_at DATETIME, 
	updated_at DATETIME, scope VARCHAR(16) DEFAULT 'company', project_ids TEXT, is_default BOOLEAN DEFAULT 0, 
	PRIMARY KEY (id)
);
CREATE TABLE sys_operation_log (
	id INTEGER NOT NULL, 
	user_id INTEGER, 
	username VARCHAR(64), 
	module VARCHAR(64), 
	operation VARCHAR(32), 
	biz_type VARCHAR(64), 
	biz_id INTEGER, 
	method VARCHAR(16), 
	params TEXT, 
	ip_address VARCHAR(64), 
	user_agent VARCHAR(256), 
	operation_time DATETIME, 
	cost_time INTEGER, 
	status VARCHAR(16), 
	error_msg TEXT, 
	changes TEXT, 
	PRIMARY KEY (id)
);
CREATE TABLE login_logs (
	id INTEGER NOT NULL, 
	user_id INTEGER, 
	username VARCHAR(64), 
	login_time DATETIME, 
	logout_time DATETIME, 
	last_active_at DATETIME, 
	ip_address VARCHAR(64), 
	user_agent VARCHAR(512), 
	browser VARCHAR(64), 
	os VARCHAR(64), 
	status VARCHAR(16), 
	fail_reason VARCHAR(128), 
	session_id VARCHAR(128), 
	PRIMARY KEY (id)
);
CREATE TABLE error_logs (
	id INTEGER NOT NULL, 
	error_time DATETIME, 
	error_type VARCHAR(128), 
	error_message TEXT, 
	stack_trace TEXT, 
	request_url VARCHAR(512), 
	request_method VARCHAR(16), 
	request_params TEXT, 
	user_id INTEGER, 
	username VARCHAR(64), 
	ip_address VARCHAR(64), 
	user_agent VARCHAR(512), 
	is_handled BOOLEAN, 
	handled_by VARCHAR(64), 
	handled_at DATETIME, 
	handle_note TEXT, 
	PRIMARY KEY (id)
);
CREATE TABLE notification_log (
	id INTEGER NOT NULL, 
	channel VARCHAR(32) NOT NULL, 
	title VARCHAR(256), 
	content TEXT, 
	recipients VARCHAR(512), 
	status VARCHAR(16), 
	error_msg TEXT, 
	created_at DATETIME, 
	PRIMARY KEY (id)
);
CREATE TABLE data_change_log (
	id INTEGER NOT NULL, 
	module VARCHAR(64), 
	operation VARCHAR(32), 
	table_name VARCHAR(64) NOT NULL, 
	record_id INTEGER NOT NULL, 
	field_name VARCHAR(64) NOT NULL, 
	field_label VARCHAR(64), 
	old_value TEXT, 
	new_value TEXT, 
	changed_by VARCHAR(64), 
	changed_by_id INTEGER, 
	changed_at DATETIME, 
	ip_address VARCHAR(64), 
	reason VARCHAR(256), 
	PRIMARY KEY (id)
);
CREATE TABLE steel_spec_weight (
	id INTEGER NOT NULL, 
	spec_type VARCHAR(32) NOT NULL, 
	spec_name VARCHAR(64) NOT NULL, 
	theoretical_weight NUMERIC(18, 4) NOT NULL, 
	unit VARCHAR(16), 
	remark VARCHAR(128), 
	PRIMARY KEY (id)
);
CREATE TABLE sys_dept (
	id INTEGER NOT NULL, 
	dept_code VARCHAR(64) NOT NULL, 
	dept_name VARCHAR(128) NOT NULL, 
	parent_id INTEGER, 
	dept_type VARCHAR(16), 
	project_id INTEGER, 
	leader VARCHAR(64), 
	sort INTEGER, 
	status BOOLEAN, 
	remark VARCHAR(256), 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	UNIQUE (dept_code), 
	FOREIGN KEY(parent_id) REFERENCES sys_dept (id), 
	FOREIGN KEY(project_id) REFERENCES projects (id)
);
CREATE TABLE sys_announcement_read (
	id INTEGER NOT NULL, 
	announcement_id INTEGER NOT NULL, 
	user_id INTEGER NOT NULL, 
	read_at DATETIME, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_announcement_user UNIQUE (announcement_id, user_id), 
	FOREIGN KEY(announcement_id) REFERENCES sys_announcement (id)
);
CREATE TABLE sys_role_menu (
	id INTEGER NOT NULL, 
	role_id INTEGER NOT NULL, 
	menu_id INTEGER NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_role_menu UNIQUE (role_id, menu_id), 
	FOREIGN KEY(role_id) REFERENCES sys_role (id), 
	FOREIGN KEY(menu_id) REFERENCES sys_menu (id)
);
CREATE TABLE suppliers (
	id INTEGER NOT NULL, 
	project_id INTEGER NOT NULL, 
	name VARCHAR(128) NOT NULL, 
	code VARCHAR(64), 
	credit_code VARCHAR(64), 
	contact_person VARCHAR(64), 
	phone VARCHAR(32), 
	legal_person VARCHAR(64), 
	address VARCHAR(256), 
	bank_name VARCHAR(128), 
	bank_account VARCHAR(64), 
	license_image VARCHAR(256), 
	license_expire_date DATE, 
	certificate_expire_date DATE, 
	opening_balance NUMERIC(18, 2), 
	source VARCHAR(16), 
	status VARCHAR(16), 
	create_dept INTEGER, 
	created_at DATETIME, is_deleted BOOLEAN DEFAULT 0, deleted_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(project_id) REFERENCES projects (id)
);
CREATE TABLE categories (
	id INTEGER NOT NULL, 
	project_id INTEGER NOT NULL, 
	parent_id INTEGER, 
	level INTEGER, 
	category_code VARCHAR(32), 
	name VARCHAR(128) NOT NULL, 
	sort_order INTEGER, 
	negative_stock_policy VARCHAR(16), 
	batch_management BOOLEAN, 
	source VARCHAR(16), 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(project_id) REFERENCES projects (id), 
	FOREIGN KEY(parent_id) REFERENCES categories (id)
);
CREATE TABLE usage_units (
	id INTEGER NOT NULL, 
	project_id INTEGER NOT NULL, 
	name VARCHAR(128) NOT NULL, 
	code VARCHAR(64), 
	manager VARCHAR(64), 
	contact_phone VARCHAR(32), 
	auth_file VARCHAR(256), 
	is_subcontractor BOOLEAN, 
	subcontract_contract VARCHAR(128), 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(project_id) REFERENCES projects (id)
);
CREATE TABLE work_numbers (
	id INTEGER NOT NULL, 
	project_id INTEGER NOT NULL, 
	code VARCHAR(64) NOT NULL, 
	division_name VARCHAR(128), 
	item_name VARCHAR(128), 
	team_name VARCHAR(128), 
	picker VARCHAR(64), 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(project_id) REFERENCES projects (id)
);
CREATE TABLE sys_dict_item (
	id INTEGER NOT NULL, 
	dict_type_id INTEGER NOT NULL, 
	item_label VARCHAR(128) NOT NULL, 
	item_value VARCHAR(128) NOT NULL, 
	sort_order INTEGER, 
	is_active BOOLEAN, 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(dict_type_id) REFERENCES sys_dict_type (id)
);
CREATE TABLE approval_branch (
	id INTEGER NOT NULL, 
	flow_id INTEGER NOT NULL, 
	branch_name VARCHAR(128) NOT NULL, 
	condition_field VARCHAR(64), 
	condition_operator VARCHAR(16), 
	condition_value VARCHAR(128), 
	condition_logic VARCHAR(16), 
	is_default BOOLEAN, 
	priority INTEGER, 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(flow_id) REFERENCES approval_flow (id)
);
CREATE TABLE turnover_material (
	id INTEGER NOT NULL, 
	project_id INTEGER NOT NULL, 
	code VARCHAR(64) NOT NULL, 
	name VARCHAR(128) NOT NULL, 
	category VARCHAR(64), 
	specification VARCHAR(128), 
	unit VARCHAR(32), 
	material_type VARCHAR(16), 
	rental_price NUMERIC(12, 4), 
	rental_unit VARCHAR(16), 
	original_value NUMERIC(18, 2), 
	amortize_months INTEGER, 
	status VARCHAR(16), 
	remark TEXT, 
	created_at DATETIME, is_deleted BOOLEAN DEFAULT 0, deleted_at DATETIME, dept_id INTEGER, 
	PRIMARY KEY (id), 
	FOREIGN KEY(project_id) REFERENCES projects (id)
);
CREATE TABLE attachments (
	id INTEGER NOT NULL, 
	project_id INTEGER, 
	module VARCHAR(64) NOT NULL, 
	biz_id INTEGER, 
	original_name VARCHAR(256) NOT NULL, 
	file_name VARCHAR(128) NOT NULL, 
	file_path VARCHAR(512) NOT NULL, 
	file_size INTEGER, 
	file_type VARCHAR(32), 
	mime_type VARCHAR(128), 
	uploaded_by VARCHAR(64), 
	uploaded_by_id INTEGER, 
	uploaded_at DATETIME, 
	is_deleted BOOLEAN, 
	deleted_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(project_id) REFERENCES projects (id)
);
CREATE TABLE period_closes (
	id INTEGER NOT NULL, 
	project_id INTEGER NOT NULL, 
	period VARCHAR(7) NOT NULL, 
	status VARCHAR(16), 
	closed_at DATETIME, 
	closed_by VARCHAR(64), 
	reopen_at DATETIME, 
	reopen_by VARCHAR(64), 
	reopen_reason VARCHAR(256), 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_project_period UNIQUE (project_id, period), 
	FOREIGN KEY(project_id) REFERENCES projects (id)
);
CREATE TABLE users (
	id INTEGER NOT NULL, 
	username VARCHAR(64) NOT NULL, 
	password_hash VARCHAR(256) NOT NULL, 
	role VARCHAR(20) NOT NULL, 
	role_id INTEGER, 
	dept_id INTEGER, 
	name VARCHAR(64), 
	department VARCHAR(64), 
	email VARCHAR(128), 
	phone VARCHAR(32), 
	data_scope VARCHAR(16), 
	allowed_projects TEXT, 
	can_view_amount BOOLEAN, 
	notify_channels TEXT, 
	per_page INTEGER, 
	created_at DATETIME, 
	last_login_at DATETIME, 
	failed_login_count INTEGER, 
	locked_until DATETIME, 
	last_login_ip VARCHAR(64), must_change_password BOOLEAN DEFAULT 0, 
	PRIMARY KEY (id), 
	FOREIGN KEY(role_id) REFERENCES sys_role (id), 
	FOREIGN KEY(dept_id) REFERENCES sys_dept (id)
);
CREATE TABLE sys_role_dept (
	id INTEGER NOT NULL, 
	role_id INTEGER NOT NULL, 
	dept_id INTEGER NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_role_dept UNIQUE (role_id, dept_id), 
	FOREIGN KEY(role_id) REFERENCES sys_role (id), 
	FOREIGN KEY(dept_id) REFERENCES sys_dept (id)
);
CREATE TABLE materials (
	id INTEGER NOT NULL, 
	project_id INTEGER NOT NULL, 
	category_id INTEGER, 
	name VARCHAR(128) NOT NULL, 
	code VARCHAR(64), 
	specification VARCHAR(256), 
	unit VARCHAR(32) NOT NULL, 
	remark TEXT, 
	source VARCHAR(16), 
	status VARCHAR(16), 
	create_dept INTEGER, 
	created_at DATETIME, is_deleted BOOLEAN DEFAULT 0, deleted_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(project_id) REFERENCES projects (id), 
	FOREIGN KEY(category_id) REFERENCES categories (id)
);
CREATE TABLE project_supplier (
	id INTEGER NOT NULL, 
	project_id INTEGER NOT NULL, 
	supplier_id INTEGER NOT NULL, 
	is_common BOOLEAN, 
	sort INTEGER, 
	create_time DATETIME, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_project_supplier_link UNIQUE (project_id, supplier_id), 
	FOREIGN KEY(project_id) REFERENCES projects (id), 
	FOREIGN KEY(supplier_id) REFERENCES suppliers (id)
);
CREATE TABLE unit_teams (
	id INTEGER NOT NULL, 
	unit_id INTEGER NOT NULL, 
	team_name VARCHAR(128) NOT NULL, 
	picker_name VARCHAR(64), 
	phone VARCHAR(32), 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(unit_id) REFERENCES usage_units (id)
);
CREATE TABLE contracts (
	id INTEGER NOT NULL, 
	project_id INTEGER NOT NULL, 
	code VARCHAR(64) NOT NULL, 
	name VARCHAR(256) NOT NULL, 
	supplier_id INTEGER NOT NULL, 
	contract_type VARCHAR(32), 
	business_type VARCHAR(32), 
	procurement_method VARCHAR(32), 
	sign_date DATE, 
	amount_with_tax NUMERIC(18, 2), 
	tax_rate NUMERIC(5, 2), 
	amount_without_tax NUMERIC(18, 2), 
	status VARCHAR(32), 
	approval_status VARCHAR(16), 
	is_final_settled BOOLEAN, 
	is_litigated BOOLEAN, 
	attachment VARCHAR(256), 
	remark TEXT, 
	created_at DATETIME, is_deleted BOOLEAN DEFAULT 0, deleted_at DATETIME, dept_id INTEGER, 
	PRIMARY KEY (id), 
	FOREIGN KEY(project_id) REFERENCES projects (id), 
	FOREIGN KEY(supplier_id) REFERENCES suppliers (id)
);
CREATE TABLE price_formula (
	id INTEGER NOT NULL, 
	project_id INTEGER NOT NULL, 
	formula_name VARCHAR(128) NOT NULL, 
	supplier_id INTEGER, 
	material_category_id INTEGER, 
	base_price_type VARCHAR(16), 
	discount_type VARCHAR(16), 
	discount_value NUMERIC(18, 4), 
	service_fee_rate NUMERIC(18, 4), 
	service_fee_fixed NUMERIC(18, 4), 
	capital_fee_rate NUMERIC(18, 4), 
	capital_fee_days INTEGER, 
	tax_rate NUMERIC(5, 2), 
	tax_included BOOLEAN, 
	status VARCHAR(16), 
	remark TEXT, 
	created_at DATETIME, float_type VARCHAR(16), float_value NUMERIC(18, 4), 
	PRIMARY KEY (id), 
	FOREIGN KEY(project_id) REFERENCES projects (id), 
	FOREIGN KEY(supplier_id) REFERENCES suppliers (id), 
	FOREIGN KEY(material_category_id) REFERENCES categories (id)
);
CREATE TABLE approval_branch_condition (
	id INTEGER NOT NULL, 
	branch_id INTEGER NOT NULL, 
	sort INTEGER, 
	condition_field VARCHAR(64) NOT NULL, 
	condition_operator VARCHAR(16) NOT NULL, 
	condition_value VARCHAR(128) NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(branch_id) REFERENCES approval_branch (id)
);
CREATE TABLE stock_check (
	id INTEGER NOT NULL, 
	check_no VARCHAR(64) NOT NULL, 
	project_id INTEGER NOT NULL, 
	check_date DATE NOT NULL, 
	check_type VARCHAR(16), 
	category_id INTEGER, 
	status VARCHAR(16), 
	checker VARCHAR(64), 
	remark TEXT, 
	created_at DATETIME, dept_id INTEGER, 
	PRIMARY KEY (id), 
	FOREIGN KEY(project_id) REFERENCES projects (id), 
	FOREIGN KEY(category_id) REFERENCES categories (id)
);
CREATE TABLE supplier_evaluation (
	id INTEGER NOT NULL, 
	supplier_id INTEGER NOT NULL, 
	evaluate_period VARCHAR(32) NOT NULL, 
	evaluate_date DATE NOT NULL, 
	evaluator VARCHAR(64), 
	quality_score INTEGER, 
	price_score INTEGER, 
	delivery_score INTEGER, 
	service_score INTEGER, 
	total_score NUMERIC(5, 2), 
	level VARCHAR(16), 
	comment TEXT, 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(supplier_id) REFERENCES suppliers (id)
);
CREATE TABLE turnover_inventory (
	id INTEGER NOT NULL, 
	project_id INTEGER NOT NULL, 
	material_id INTEGER NOT NULL, 
	quantity NUMERIC(18, 4), 
	rent_out_qty NUMERIC(18, 4), 
	PRIMARY KEY (id), 
	CONSTRAINT uq_turnover_inv UNIQUE (project_id, material_id), 
	FOREIGN KEY(project_id) REFERENCES projects (id), 
	FOREIGN KEY(material_id) REFERENCES turnover_material (id)
);
CREATE TABLE turnover_record (
	id INTEGER NOT NULL, 
	project_id INTEGER NOT NULL, 
	material_id INTEGER NOT NULL, 
	team VARCHAR(128), 
	qty NUMERIC(18, 4), 
	returned_qty NUMERIC(18, 4), 
	lost_qty NUMERIC(18, 4), 
	out_date DATE NOT NULL, 
	expect_return_date DATE, 
	actual_return_date DATE, 
	status VARCHAR(16), 
	rent_fee NUMERIC(18, 2), 
	remark TEXT, 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(project_id) REFERENCES projects (id), 
	FOREIGN KEY(material_id) REFERENCES turnover_material (id)
);
CREATE TABLE equipment (
	id INTEGER NOT NULL, 
	project_id INTEGER NOT NULL, 
	code VARCHAR(64) NOT NULL, 
	name VARCHAR(128) NOT NULL, 
	source_type VARCHAR(16), 
	category VARCHAR(64), 
	specification VARCHAR(128), 
	manufacturer VARCHAR(128), 
	purchase_date DATE, 
	original_value NUMERIC(18, 2), 
	use_years INTEGER, 
	residual_rate NUMERIC(5, 2), 
	supplier_id INTEGER, 
	rent_type VARCHAR(16), 
	rent_unit_price NUMERIC(18, 2), 
	rent_period INTEGER, 
	entry_date DATE, 
	expected_exit_date DATE, 
	entry_exit_fee NUMERIC(18, 2), 
	deposit NUMERIC(18, 2), 
	labor_team VARCHAR(128), 
	exit_date DATE, 
	department VARCHAR(64), 
	responsible VARCHAR(64), 
	location VARCHAR(128), 
	status VARCHAR(16), 
	photo VARCHAR(256), 
	remark TEXT, 
	is_deleted BOOLEAN, 
	deleted_at DATETIME, 
	created_at DATETIME, dept_id INTEGER, location_lat FLOAT, location_lng FLOAT, location_accuracy FLOAT, location_time DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(project_id) REFERENCES projects (id), 
	FOREIGN KEY(supplier_id) REFERENCES suppliers (id)
);
CREATE TABLE concrete_ticket (
	id INTEGER NOT NULL, 
	project_id INTEGER NOT NULL, 
	ticket_no VARCHAR(64) NOT NULL, 
	supplier_id INTEGER, 
	supplier_name VARCHAR(128), 
	strength_grade VARCHAR(32), 
	pour_part VARCHAR(128), 
	work_number_id INTEGER, 
	vehicle_count INTEGER, 
	volume NUMERIC(18, 4), 
	arrival_time DATETIME, 
	vehicle_no VARCHAR(32), 
	driver_name VARCHAR(32), 
	slump VARCHAR(32), 
	temperature VARCHAR(32), 
	photo_path VARCHAR(256), 
	is_reconciled BOOLEAN, 
	is_transferred BOOLEAN, 
	location_lat FLOAT, 
	location_lng FLOAT, 
	location_accuracy FLOAT, 
	location_time DATETIME, 
	remark TEXT, 
	created_at DATETIME, dept_id INTEGER, contract_id INTEGER, material_id INTEGER, 
	PRIMARY KEY (id), 
	FOREIGN KEY(project_id) REFERENCES projects (id), 
	FOREIGN KEY(supplier_id) REFERENCES suppliers (id), 
	FOREIGN KEY(work_number_id) REFERENCES work_numbers (id)
);
CREATE TABLE subcontract_deduction (
	id INTEGER NOT NULL, 
	project_id INTEGER NOT NULL, 
	usage_unit_id INTEGER NOT NULL, 
	period VARCHAR(16) NOT NULL, 
	total_quantity NUMERIC(18, 4), 
	total_amount NUMERIC(18, 2), 
	status VARCHAR(16), 
	remark TEXT, 
	created_at DATETIME, 
	updated_at DATETIME, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_proj_unit_period UNIQUE (project_id, usage_unit_id, period), 
	FOREIGN KEY(project_id) REFERENCES projects (id), 
	FOREIGN KEY(usage_unit_id) REFERENCES usage_units (id)
);
CREATE TABLE sys_user_project (
	id INTEGER NOT NULL, 
	user_id INTEGER NOT NULL, 
	project_id INTEGER NOT NULL, 
	is_main BOOLEAN, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_user_project UNIQUE (user_id, project_id), 
	FOREIGN KEY(user_id) REFERENCES users (id), 
	FOREIGN KEY(project_id) REFERENCES projects (id)
);
CREATE TABLE project_material (
	id INTEGER NOT NULL, 
	project_id INTEGER NOT NULL, 
	material_id INTEGER NOT NULL, 
	is_common BOOLEAN, 
	sort INTEGER, 
	create_time DATETIME, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_project_material_link UNIQUE (project_id, material_id), 
	FOREIGN KEY(project_id) REFERENCES projects (id), 
	FOREIGN KEY(material_id) REFERENCES materials (id)
);
CREATE TABLE material_quotas (
	id INTEGER NOT NULL, 
	project_id INTEGER NOT NULL, 
	work_number_id INTEGER NOT NULL, 
	material_id INTEGER NOT NULL, 
	quota_type VARCHAR(16), 
	quota_quantity NUMERIC(18, 4), 
	quota_amount NUMERIC(18, 2), 
	created_at DATETIME, 
	updated_at DATETIME, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_worknum_material UNIQUE (work_number_id, material_id), 
	FOREIGN KEY(project_id) REFERENCES projects (id), 
	FOREIGN KEY(work_number_id) REFERENCES work_numbers (id), 
	FOREIGN KEY(material_id) REFERENCES materials (id)
);
CREATE TABLE contract_items (
	id INTEGER NOT NULL, 
	contract_id INTEGER NOT NULL, 
	material_id INTEGER NOT NULL, 
	price_type VARCHAR(32), 
	quantity NUMERIC(18, 4), 
	tax_rate NUMERIC(5, 2), 
	unit_price_with_tax NUMERIC(18, 4), 
	unit_price_without_tax NUMERIC(18, 4), 
	amount_with_tax NUMERIC(18, 2), 
	remark VARCHAR(256), 
	total_in_qty NUMERIC(18, 4), 
	PRIMARY KEY (id), 
	FOREIGN KEY(contract_id) REFERENCES contracts (id), 
	FOREIGN KEY(material_id) REFERENCES materials (id)
);
CREATE TABLE invoices (
	id INTEGER NOT NULL, 
	project_id INTEGER NOT NULL, 
	contract_id INTEGER NOT NULL, 
	supplier_id INTEGER NOT NULL, 
	invoice_code VARCHAR(64), 
	invoice_number VARCHAR(64), 
	invoice_date DATE, 
	amount_with_tax NUMERIC(18, 2), 
	tax_rate NUMERIC(5, 2), 
	amount_without_tax NUMERIC(18, 2), 
	file_path VARCHAR(256), 
	remark TEXT, 
	created_at DATETIME, is_deleted BOOLEAN DEFAULT 0, 
	PRIMARY KEY (id), 
	FOREIGN KEY(project_id) REFERENCES projects (id), 
	FOREIGN KEY(contract_id) REFERENCES contracts (id), 
	FOREIGN KEY(supplier_id) REFERENCES suppliers (id)
);
CREATE TABLE stock_ins (
	id INTEGER NOT NULL, 
	project_id INTEGER NOT NULL, 
	code VARCHAR(64) NOT NULL, 
	stock_in_date DATE, 
	stock_in_type VARCHAR(32), 
	contract_id INTEGER, 
	supplier_id INTEGER, 
	operator VARCHAR(64), 
	remark TEXT, 
	total_quantity NUMERIC(18, 4), 
	total_amount NUMERIC(18, 2), 
	estimated_amount NUMERIC(18, 2), 
	actual_amount NUMERIC(18, 2), 
	is_reconciled BOOLEAN, 
	is_initial BOOLEAN, 
	approval_status VARCHAR(16), 
	quality_status VARCHAR(16), 
	quality_checker VARCHAR(64), 
	quality_check_time DATETIME, 
	quality_remark TEXT, 
	location_lat FLOAT, 
	location_lng FLOAT, 
	location_accuracy FLOAT, 
	location_time DATETIME, 
	created_at DATETIME, is_deleted BOOLEAN DEFAULT 0, deleted_at DATETIME, dept_id INTEGER, 
	PRIMARY KEY (id), 
	FOREIGN KEY(project_id) REFERENCES projects (id), 
	FOREIGN KEY(contract_id) REFERENCES contracts (id), 
	FOREIGN KEY(supplier_id) REFERENCES suppliers (id)
);
CREATE TABLE inventory (
	id INTEGER NOT NULL, 
	project_id INTEGER NOT NULL, 
	material_id INTEGER NOT NULL, 
	quantity NUMERIC(18, 4), 
	in_transit_qty NUMERIC(18, 4), 
	estimated_amount NUMERIC(18, 2), 
	actual_amount NUMERIC(18, 2), 
	updated_at DATETIME, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_project_material UNIQUE (project_id, material_id), 
	FOREIGN KEY(project_id) REFERENCES projects (id), 
	FOREIGN KEY(material_id) REFERENCES materials (id)
);
CREATE TABLE stock_outs (
	id INTEGER NOT NULL, 
	project_id INTEGER NOT NULL, 
	code VARCHAR(64) NOT NULL, 
	stock_out_date DATE, 
	stock_out_type VARCHAR(32), 
	usage_unit_id INTEGER, 
	work_number_id INTEGER, 
	issue_location VARCHAR(256), 
	purpose VARCHAR(256), 
	team_id INTEGER, 
	operator VARCHAR(64), 
	remark TEXT, 
	total_quantity NUMERIC(18, 4), 
	total_amount NUMERIC(18, 2), 
	is_reconciled BOOLEAN, 
	approval_status VARCHAR(16), 
	location_lat FLOAT, 
	location_lng FLOAT, 
	location_accuracy FLOAT, 
	location_time DATETIME, 
	created_at DATETIME, is_deleted BOOLEAN DEFAULT 0, deleted_at DATETIME, dept_id INTEGER, 
	PRIMARY KEY (id), 
	FOREIGN KEY(project_id) REFERENCES projects (id), 
	FOREIGN KEY(usage_unit_id) REFERENCES usage_units (id), 
	FOREIGN KEY(work_number_id) REFERENCES work_numbers (id), 
	FOREIGN KEY(team_id) REFERENCES unit_teams (id)
);
CREATE TABLE reconciliations (
	id INTEGER NOT NULL, 
	project_id INTEGER NOT NULL, 
	code VARCHAR(64) NOT NULL, 
	supplier_id INTEGER NOT NULL, 
	contract_id INTEGER NOT NULL, 
	price_formula_id INTEGER, 
	start_date DATE NOT NULL, 
	end_date DATE NOT NULL, 
	status VARCHAR(32), 
	total_amount NUMERIC(18, 2), 
	total_amount_without_tax NUMERIC(18, 2), 
	total_tax_amount NUMERIC(18, 2), 
	approval_status VARCHAR(16), 
	remark TEXT, 
	created_at DATETIME, 
	confirmed_at DATETIME, 
	confirmed_by VARCHAR(64), is_deleted BOOLEAN DEFAULT 0, deleted_at DATETIME, dept_id INTEGER, 
	PRIMARY KEY (id), 
	FOREIGN KEY(project_id) REFERENCES projects (id), 
	FOREIGN KEY(supplier_id) REFERENCES suppliers (id), 
	FOREIGN KEY(contract_id) REFERENCES contracts (id), 
	FOREIGN KEY(price_formula_id) REFERENCES price_formula (id)
);
CREATE TABLE operation_logs (
	id INTEGER NOT NULL, 
	user_id INTEGER, 
	username VARCHAR(64), 
	action VARCHAR(32) NOT NULL, 
	module VARCHAR(64), 
	description TEXT, 
	ip_address VARCHAR(64), 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);
CREATE TABLE approval_node (
	id INTEGER NOT NULL, 
	flow_id INTEGER NOT NULL, 
	branch_id INTEGER, 
	node_order INTEGER NOT NULL, 
	node_name VARCHAR(128) NOT NULL, 
	approve_type VARCHAR(16) NOT NULL, 
	approve_role VARCHAR(64), 
	approve_user_id INTEGER, 
	pass_rule VARCHAR(16), 
	sign_required BOOLEAN, 
	PRIMARY KEY (id), 
	FOREIGN KEY(flow_id) REFERENCES approval_flow (id), 
	FOREIGN KEY(branch_id) REFERENCES approval_branch (id), 
	FOREIGN KEY(approve_user_id) REFERENCES users (id)
);
CREATE TABLE stock_check_item (
	id INTEGER NOT NULL, 
	check_id INTEGER NOT NULL, 
	material_id INTEGER NOT NULL, 
	material_name VARCHAR(128) NOT NULL, 
	specification VARCHAR(128), 
	unit VARCHAR(32), 
	book_qty NUMERIC(18, 4), 
	actual_qty NUMERIC(18, 4), 
	diff_reason VARCHAR(256), 
	PRIMARY KEY (id), 
	FOREIGN KEY(check_id) REFERENCES stock_check (id), 
	FOREIGN KEY(material_id) REFERENCES materials (id)
);
CREATE TABLE equipment_status_log (
	id INTEGER NOT NULL, 
	equipment_id INTEGER NOT NULL, 
	old_status VARCHAR(16), 
	new_status VARCHAR(16) NOT NULL, 
	exit_date DATE, 
	operator_id INTEGER, 
	operator_name VARCHAR(64), 
	remark TEXT, 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(equipment_id) REFERENCES equipment (id), 
	FOREIGN KEY(operator_id) REFERENCES users (id)
);
CREATE TABLE equipment_rent_settle (
	id INTEGER NOT NULL, 
	settle_no VARCHAR(64) NOT NULL, 
	equipment_id INTEGER NOT NULL, 
	supplier_id INTEGER, 
	settle_period VARCHAR(16), 
	settle_start_date DATE, 
	settle_end_date DATE, 
	rent_type VARCHAR(16), 
	unit_price NUMERIC(18, 2), 
	quantity NUMERIC(18, 2), 
	rent_amount NUMERIC(18, 2), 
	other_fee NUMERIC(18, 2), 
	total_amount NUMERIC(18, 2), 
	status VARCHAR(16), 
	remark TEXT, 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(equipment_id) REFERENCES equipment (id), 
	FOREIGN KEY(supplier_id) REFERENCES suppliers (id)
);
CREATE TABLE equipment_maintenance (
	id INTEGER NOT NULL, 
	equipment_id INTEGER NOT NULL, 
	maintain_date DATE NOT NULL, 
	maintain_type VARCHAR(16), 
	content TEXT, 
	cost NUMERIC(18, 2), 
	vendor VARCHAR(128), 
	next_maintain_date DATE, 
	operator VARCHAR(64), 
	remark TEXT, 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(equipment_id) REFERENCES equipment (id)
);
CREATE TABLE equipment_inspection (
	id INTEGER NOT NULL, 
	project_id INTEGER NOT NULL, 
	plan_name VARCHAR(128) NOT NULL, 
	plan_type VARCHAR(32), 
	cycle VARCHAR(16), 
	inspect_items TEXT, 
	equipment_category VARCHAR(64), 
	responsible_id INTEGER, 
	responsible_name VARCHAR(64), 
	start_date DATE, 
	end_date DATE, 
	next_inspect_date DATE, 
	status VARCHAR(16), 
	remark TEXT, 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(project_id) REFERENCES projects (id), 
	FOREIGN KEY(responsible_id) REFERENCES users (id)
);
CREATE TABLE material_qrcode (
	id INTEGER NOT NULL, 
	project_id INTEGER NOT NULL, 
	material_id INTEGER NOT NULL, 
	qr_code VARCHAR(256) NOT NULL, 
	batch_no VARCHAR(64), 
	print_count INTEGER, 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(project_id) REFERENCES projects (id), 
	FOREIGN KEY(material_id) REFERENCES materials (id), 
	UNIQUE (qr_code)
);
CREATE TABLE sys_message (
	id INTEGER NOT NULL, 
	user_id INTEGER NOT NULL, 
	title VARCHAR(128) NOT NULL, 
	content TEXT, 
	msg_type VARCHAR(16), 
	biz_type VARCHAR(32), 
	biz_id INTEGER, 
	url VARCHAR(256), 
	is_read BOOLEAN, 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);
CREATE TABLE movement_snapshots (
	id INTEGER NOT NULL, 
	project_id INTEGER NOT NULL, 
	period VARCHAR(7) NOT NULL, 
	material_id INTEGER NOT NULL, 
	begin_qty NUMERIC(18, 4), 
	begin_amount NUMERIC(18, 2), 
	in_qty NUMERIC(18, 4), 
	in_amount NUMERIC(18, 2), 
	out_qty NUMERIC(18, 4), 
	out_amount NUMERIC(18, 2), 
	end_qty NUMERIC(18, 4), 
	end_amount NUMERIC(18, 2), 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_proj_period_mat UNIQUE (project_id, period, material_id), 
	FOREIGN KEY(project_id) REFERENCES projects (id), 
	FOREIGN KEY(material_id) REFERENCES materials (id)
);
CREATE TABLE inventory_batch (
	id INTEGER NOT NULL, 
	project_id INTEGER NOT NULL, 
	material_id INTEGER NOT NULL, 
	batch_no VARCHAR(64) NOT NULL, 
	production_date DATE, 
	shelf_life_days INTEGER, 
	expire_date DATE, 
	quantity NUMERIC(18, 4), 
	unit_price NUMERIC(18, 4), 
	stock_in_date DATE, 
	created_at DATETIME, 
	updated_at DATETIME, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_proj_mat_batch UNIQUE (project_id, material_id, batch_no), 
	FOREIGN KEY(project_id) REFERENCES projects (id), 
	FOREIGN KEY(material_id) REFERENCES materials (id)
);
CREATE TABLE material_scrap (
	id INTEGER NOT NULL, 
	project_id INTEGER NOT NULL, 
	code VARCHAR(64) NOT NULL, 
	scrap_date DATE NOT NULL, 
	usage_unit_id INTEGER, 
	reason VARCHAR(32) NOT NULL, 
	remark TEXT, 
	photo_path VARCHAR(256), 
	applicant_id INTEGER, 
	applicant_name VARCHAR(64), 
	approval_status VARCHAR(16), 
	approval_instance_id INTEGER, 
	total_quantity NUMERIC(18, 4), 
	total_amount NUMERIC(18, 2), 
	location_lat FLOAT, 
	location_lng FLOAT, 
	location_accuracy FLOAT, 
	location_time DATETIME, 
	created_at DATETIME, dept_id INTEGER, 
	PRIMARY KEY (id), 
	FOREIGN KEY(project_id) REFERENCES projects (id), 
	FOREIGN KEY(usage_unit_id) REFERENCES usage_units (id), 
	FOREIGN KEY(applicant_id) REFERENCES users (id)
);
CREATE TABLE barcode_label (
	id INTEGER NOT NULL, 
	project_id INTEGER, 
	material_id INTEGER, 
	material_name VARCHAR(128), 
	material_code VARCHAR(64), 
	spec VARCHAR(256), 
	unit VARCHAR(32), 
	label_size VARCHAR(32), 
	quantity INTEGER, 
	created_at DATETIME, 
	created_by INTEGER, 
	PRIMARY KEY (id), 
	FOREIGN KEY(project_id) REFERENCES projects (id), 
	FOREIGN KEY(material_id) REFERENCES materials (id), 
	FOREIGN KEY(created_by) REFERENCES users (id)
);
CREATE TABLE stock_in_items (
	id INTEGER NOT NULL, 
	stock_in_id INTEGER NOT NULL, 
	material_id INTEGER NOT NULL, 
	quantity NUMERIC(18, 4), 
	unit_price NUMERIC(18, 4), 
	amount NUMERIC(18, 2), 
	contract_item_id INTEGER, 
	is_over_contract BOOLEAN, 
	price_status VARCHAR(16), 
	batch_no VARCHAR(64), 
	production_date DATE, 
	shelf_life_days INTEGER, 
	expire_date DATE, 
	PRIMARY KEY (id), 
	FOREIGN KEY(stock_in_id) REFERENCES stock_ins (id), 
	FOREIGN KEY(material_id) REFERENCES materials (id), 
	FOREIGN KEY(contract_item_id) REFERENCES contract_items (id)
);
CREATE TABLE stock_out_items (
	id INTEGER NOT NULL, 
	stock_out_id INTEGER NOT NULL, 
	material_id INTEGER NOT NULL, 
	quantity NUMERIC(18, 4), 
	unit_price NUMERIC(18, 4), 
	amount NUMERIC(18, 2), 
	batch_no VARCHAR(64), 
	PRIMARY KEY (id), 
	FOREIGN KEY(stock_out_id) REFERENCES stock_outs (id), 
	FOREIGN KEY(material_id) REFERENCES materials (id)
);
CREATE TABLE reconciliation_items (
	id INTEGER NOT NULL, 
	reconciliation_id INTEGER NOT NULL, 
	material_id INTEGER NOT NULL, 
	cost_subject VARCHAR(128), 
	price_type VARCHAR(32), 
	quantity NUMERIC(18, 4), 
	unit_price NUMERIC(18, 4), 
	amount NUMERIC(18, 2), 
	base_price NUMERIC(18, 4), 
	settlement_price NUMERIC(18, 4), 
	amount_without_tax NUMERIC(18, 2), 
	tax_amount NUMERIC(18, 2), 
	amount_with_tax NUMERIC(18, 2), 
	calc_detail TEXT, 
	specification VARCHAR(256), 
	unit VARCHAR(32), 
	source_stock_in_ids TEXT, 
	PRIMARY KEY (id), 
	FOREIGN KEY(reconciliation_id) REFERENCES reconciliations (id), 
	FOREIGN KEY(material_id) REFERENCES materials (id)
);
CREATE TABLE approval_instance (
	id INTEGER NOT NULL, 
	flow_id INTEGER NOT NULL, 
	branch_id INTEGER, 
	biz_type VARCHAR(32) NOT NULL, 
	biz_id INTEGER NOT NULL, 
	biz_title VARCHAR(256), 
	applicant_id INTEGER NOT NULL, 
	submit_time DATETIME, 
	status VARCHAR(16), 
	current_node_id INTEGER, 
	reject_reason TEXT, 
	created_at DATETIME, project_id INTEGER, 
	PRIMARY KEY (id), 
	FOREIGN KEY(flow_id) REFERENCES approval_flow (id), 
	FOREIGN KEY(branch_id) REFERENCES approval_branch (id), 
	FOREIGN KEY(applicant_id) REFERENCES users (id), 
	FOREIGN KEY(current_node_id) REFERENCES approval_node (id)
);
CREATE TABLE equipment_inspection_task (
	id INTEGER NOT NULL, 
	project_id INTEGER NOT NULL, 
	inspection_id INTEGER NOT NULL, 
	equipment_id INTEGER NOT NULL, 
	task_no VARCHAR(64) NOT NULL, 
	plan_inspect_date DATE NOT NULL, 
	assignee_id INTEGER, 
	assignee_name VARCHAR(64), 
	status VARCHAR(16), 
	remark TEXT, 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(project_id) REFERENCES projects (id), 
	FOREIGN KEY(inspection_id) REFERENCES equipment_inspection (id), 
	FOREIGN KEY(equipment_id) REFERENCES equipment (id), 
	FOREIGN KEY(assignee_id) REFERENCES users (id)
);
CREATE TABLE material_scrap_item (
	id INTEGER NOT NULL, 
	scrap_id INTEGER NOT NULL, 
	material_id INTEGER NOT NULL, 
	batch_no VARCHAR(64), 
	quantity NUMERIC(18, 4), 
	unit_price NUMERIC(18, 4), 
	amount NUMERIC(18, 2), 
	reason_detail VARCHAR(256), 
	PRIMARY KEY (id), 
	FOREIGN KEY(scrap_id) REFERENCES material_scrap (id), 
	FOREIGN KEY(material_id) REFERENCES materials (id)
);
CREATE TABLE approval_record (
	id INTEGER NOT NULL, 
	instance_id INTEGER NOT NULL, 
	node_id INTEGER, 
	approver_id INTEGER NOT NULL, 
	action VARCHAR(16) NOT NULL, 
	opinion TEXT, 
	approve_time DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(instance_id) REFERENCES approval_instance (id), 
	FOREIGN KEY(node_id) REFERENCES approval_node (id), 
	FOREIGN KEY(approver_id) REFERENCES users (id)
);
CREATE TABLE purchase_requisition (
	id INTEGER NOT NULL, 
	pr_no VARCHAR(64) NOT NULL, 
	project_id INTEGER NOT NULL, 
	apply_dept VARCHAR(64), 
	apply_user VARCHAR(64), 
	apply_date DATE NOT NULL, 
	demand_date DATE, 
	status VARCHAR(16), 
	approval_instance_id INTEGER, 
	remark TEXT, 
	created_at DATETIME, dept_id INTEGER, 
	PRIMARY KEY (id), 
	FOREIGN KEY(project_id) REFERENCES projects (id), 
	FOREIGN KEY(approval_instance_id) REFERENCES approval_instance (id)
);
CREATE TABLE material_transfer (
	id INTEGER NOT NULL, 
	transfer_no VARCHAR(64) NOT NULL, 
	from_project_id INTEGER NOT NULL, 
	to_project_id INTEGER NOT NULL, 
	transfer_date DATE NOT NULL, 
	status VARCHAR(16), 
	applicant VARCHAR(64), 
	handler VARCHAR(64), 
	remark TEXT, 
	approval_instance_id INTEGER, 
	created_at DATETIME, dept_id INTEGER, 
	PRIMARY KEY (id), 
	FOREIGN KEY(from_project_id) REFERENCES projects (id), 
	FOREIGN KEY(to_project_id) REFERENCES projects (id), 
	FOREIGN KEY(approval_instance_id) REFERENCES approval_instance (id)
);
CREATE TABLE equipment_inspection_record (
	id INTEGER NOT NULL, 
	project_id INTEGER NOT NULL, 
	task_id INTEGER, 
	equipment_id INTEGER NOT NULL, 
	inspect_date DATE NOT NULL, 
	inspector_id INTEGER, 
	inspector_name VARCHAR(64), 
	overall_status VARCHAR(16), 
	items_result TEXT, 
	meter_reading VARCHAR(64), 
	issue_desc TEXT, 
	auto_maintenance BOOLEAN, 
	remark TEXT, 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(project_id) REFERENCES projects (id), 
	FOREIGN KEY(task_id) REFERENCES equipment_inspection_task (id), 
	FOREIGN KEY(equipment_id) REFERENCES equipment (id), 
	FOREIGN KEY(inspector_id) REFERENCES users (id)
);
CREATE TABLE purchase_requisition_item (
	id INTEGER NOT NULL, 
	pr_id INTEGER NOT NULL, 
	material_id INTEGER NOT NULL, 
	material_name VARCHAR(128) NOT NULL, 
	specification VARCHAR(128), 
	unit VARCHAR(32), 
	apply_qty NUMERIC(18, 4), 
	approve_qty NUMERIC(18, 4), 
	purpose VARCHAR(256), 
	converted BOOLEAN, 
	PRIMARY KEY (id), 
	FOREIGN KEY(pr_id) REFERENCES purchase_requisition (id), 
	FOREIGN KEY(material_id) REFERENCES materials (id)
);
CREATE TABLE material_transfer_item (
	id INTEGER NOT NULL, 
	transfer_id INTEGER NOT NULL, 
	material_id INTEGER NOT NULL, 
	material_name VARCHAR(128) NOT NULL, 
	specification VARCHAR(128), 
	unit VARCHAR(32), 
	transfer_qty NUMERIC(18, 4), 
	out_qty NUMERIC(18, 4), 
	in_qty NUMERIC(18, 4), 
	PRIMARY KEY (id), 
	FOREIGN KEY(transfer_id) REFERENCES material_transfer (id), 
	FOREIGN KEY(material_id) REFERENCES materials (id)
);
CREATE INDEX ix_payment_applications_application_code ON payment_applications (application_code);
