CREATE UNIQUE INDEX ix_sys_dict_type_dict_type ON sys_dict_type (dict_type);
CREATE INDEX ix_approval_flow_biz_type ON approval_flow (biz_type);
CREATE UNIQUE INDEX ix_approval_flow_flow_code ON approval_flow (flow_code);
CREATE INDEX ix_login_logs_login_time ON login_logs (login_time);
CREATE INDEX ix_login_logs_username ON login_logs (username);
CREATE INDEX ix_login_logs_user_id ON login_logs (user_id);
CREATE INDEX ix_error_logs_error_time ON error_logs (error_time);
CREATE INDEX ix_turnover_material_code ON turnover_material (code);
CREATE INDEX ix_attachments_module ON attachments (module);
CREATE INDEX ix_attachments_biz_id ON attachments (biz_id);
CREATE UNIQUE INDEX ix_users_username ON users (username);
CREATE INDEX ix_contracts_code ON contracts (code);
CREATE UNIQUE INDEX ix_stock_check_check_no ON stock_check (check_no);
CREATE INDEX ix_equipment_code ON equipment (code);
CREATE INDEX ix_concrete_ticket_project_id ON concrete_ticket (project_id);
CREATE INDEX ix_subcontract_deduction_project_id ON subcontract_deduction (project_id);
CREATE INDEX ix_stock_ins_code ON stock_ins (code);
CREATE INDEX ix_stock_outs_code ON stock_outs (code);
CREATE INDEX ix_reconciliations_code ON reconciliations (code);
CREATE INDEX ix_equipment_status_log_equipment_id ON equipment_status_log (equipment_id);
CREATE UNIQUE INDEX ix_equipment_rent_settle_settle_no ON equipment_rent_settle (settle_no);
CREATE INDEX ix_equipment_rent_settle_equipment_id ON equipment_rent_settle (equipment_id);
CREATE INDEX ix_sys_message_is_read ON sys_message (is_read);
CREATE INDEX ix_sys_message_user_id ON sys_message (user_id);
CREATE INDEX ix_inventory_batch_expire_date ON inventory_batch (expire_date);
CREATE INDEX ix_inventory_batch_project_id ON inventory_batch (project_id);
CREATE INDEX ix_inventory_batch_material_id ON inventory_batch (material_id);
CREATE INDEX ix_material_scrap_project_id ON material_scrap (project_id);
CREATE INDEX ix_approval_instance_biz_id ON approval_instance (biz_id);
CREATE INDEX ix_approval_instance_biz_type ON approval_instance (biz_type);
CREATE INDEX ix_approval_instance_status ON approval_instance (status);
CREATE INDEX ix_equipment_inspection_task_task_no ON equipment_inspection_task (task_no);
